/// <summary>Literal accepted vectors and genuine original corpus through the actual journal's complete dispatch.</summary>
public sealed class FileJournalRecordTemporalTests
{
    internal static JsonDocument Vectors() => JsonDocument.Parse(VectorJson);
    internal static JsonElement Event(string id)
    {
        using var vectors = Vectors();
        return vectors.RootElement.GetProperty("events").EnumerateArray().Single(value => value.GetProperty("id").GetString() == id).Clone();
    }
    internal static byte[] Mixed(string id)
    {
        using var vectors = Vectors();
        return Convert.FromHexString(vectors.RootElement.GetProperty("mixed_journals").EnumerateArray()
            .Single(value => value.GetProperty("id").GetString() == id).GetProperty("utf8_hex").GetString()!);
    }
    internal static RecordWriteRow Row(JsonElement entry)
    {
        var value = entry.GetProperty("Row");
        string S(string name) => value.GetProperty(name).GetString()!;
        string? N(string name) => value.TryGetProperty(name, out var property) ? property.GetString() : null;
        return new(S("Tenant"), S("RecordId"), S("RecordTypeId"), S("Version"), S("DefinitionDigest"), new(S("Schema")),
            S("ActorId"), S("OperationId"), N("RequestedVersion"), S("IntentEncodingVersion"), S("IntentDigest"),
            Convert.FromBase64String(S("Body")), Date(S("RecordedAt")))
        {
            PublicationVersionId = N("PublicationVersionId"), OriginatorId = N("OriginatorId"),
            AcceptedCommandId = N("AcceptedCommandId"), AcceptanceAuditId = N("AcceptanceAuditId"),
        };
    }
    internal static KernelAuditEvidence Audit(JsonElement entry)
    {
        var value = entry.GetProperty("Audit");
        return new(value.GetProperty("AuditId").GetString()!, value.GetProperty("ActorId").GetString()!,
            Date(value.GetProperty("RecordedAt").GetString()!), Convert.FromBase64String(value.GetProperty("Payload").GetString()!))
        {
            AuthoritySnapshot = Convert.FromBase64String(value.GetProperty("AuthoritySnapshot").GetString()!),
            OriginatorId = value.GetProperty("OriginatorId").GetString(),
        };
    }
    internal static RecordTemporalEvidence Evidence(JsonElement value)
    {
        RecordTemporalBasis? ReadBasis(JsonElement basis) => basis.ValueKind == JsonValueKind.Null ? null
            : new(basis.GetProperty("Revision").GetInt64(), basis.GetProperty("Hash").GetString()!);
        DateTimeOffset? To(JsonElement period) => period.GetProperty("EffectiveTo").ValueKind == JsonValueKind.Null ? null
            : Date(period.GetProperty("EffectiveTo").GetString()!);
        return new(value.GetProperty("Revision").GetInt64(), ReadBasis(value.GetProperty("Predecessor")),
            Array.AsReadOnly(value.GetProperty("Supersedes").EnumerateArray().Select(segment => new RecordTemporalSupersededSegment(
                ReadBasis(segment.GetProperty("Revision"))!, Date(segment.GetProperty("EffectiveFrom").GetString()!), To(segment))).ToArray()),
            Date(value.GetProperty("EffectiveFrom").GetString()!), To(value), value.GetProperty("Reason").GetString(),
            Date(value.GetProperty("AuthorityRecordedAt").GetString()!));
    }
    internal static async Task<RecordTemporalCommit> AppendTemporal(IRecordTemporalWritePort store, JsonElement referenceEvent,
        CancellationToken cancellationToken = default)
    {
        var entry = referenceEvent.GetProperty("entry");
        var row = Row(entry);
        var evidence = Evidence(entry.GetProperty("Temporal"));
        var operation = entry.GetProperty("Operation");
        await using var transaction = await store.BeginAsync(cancellationToken);
        await transaction.StageOperationAsync(new(operation.GetProperty("CommandId").GetString()!,
            operation.GetProperty("IdempotencyKey").GetString()!, operation.GetProperty("Fingerprint").GetString()!), cancellationToken);
        await transaction.StageRecordAsync(new(evidence.Revision == 1 ? RecordTemporalCommandKind.Create : RecordTemporalCommandKind.Amend,
            row, evidence.Predecessor, evidence.EffectiveFrom, evidence.EffectiveTo, evidence.Reason), cancellationToken);
        await transaction.StageAuditAsync(Audit(entry), cancellationToken);
        return await transaction.CommitAsync(cancellationToken);
    }
    internal static async Task<RecordWriteCommit> AppendOrdinary(FileJournalRecordWriteStore store, RecordWriteRow row,
        RecordWriteOperationKey? suppliedKey = null, CancellationToken cancellationToken = default)
    {
        var key = suppliedKey ?? new(row.Tenant, row.ActorId, row.OperationId);
        await using var transaction = await store.BeginAsync(cancellationToken);
        await transaction.StageOperationAsync(new(row.RecordId, key.IdempotencyKey, row.IntentDigest), cancellationToken);
        await transaction.StageRecordAsync(row, cancellationToken);
        await transaction.StageAuditAsync(new("ordinary-audit-" + row.OperationId, row.ActorId, row.RecordedAt, ReadOnlyMemory<byte>.Empty)
            { OriginatorId = row.OriginatorId }, cancellationToken);
        return await transaction.CommitAsync(cancellationToken);
    }
    internal static void OriginalReceipt(JsonElement expected, RecordWriteReceipt? actual)
    {
        Assert.NotNull(actual);
        Assert.Equal(expected.GetProperty("RecordId").GetString(), actual.RecordId);
        Assert.Equal(expected.GetProperty("OperationId").GetString(), actual.OperationId);
        Assert.Equal(expected.GetProperty("RecordTypeId").GetString(), actual.RecordTypeId);
        Assert.Equal(expected.GetProperty("Version").GetString(), actual.Version);
        Assert.Equal(expected.GetProperty("DefinitionDigest").GetString(), actual.DefinitionDigest);
        Assert.Equal(expected.GetProperty("Schema").GetString(), actual.Schema.Value);
        Assert.True(Date(expected.GetProperty("RecordedAt").GetString()!).EqualsExact(actual.RecordedAt));
    }
    private static RecordWriteOperationKey OriginalKey(RecordWriteRow row)
        => new(row.Tenant, row.OriginatorId ?? row.ActorId, row.OperationId)
            { Origin = row.AcceptedCommandId is null ? null : "accepted-command" };
    private sealed class JournalPath : IDisposable
    {
        internal string DirectoryName { get; } = Path.Combine(Path.GetTempPath(), "temporal-journal-" + Guid.NewGuid().ToString("N"));
        internal string FileName => Path.Combine(DirectoryName, "records.json");
        internal JournalPath() => Directory.CreateDirectory(DirectoryName);
        public void Dispose() { if (Directory.Exists(DirectoryName)) Directory.Delete(DirectoryName, true); }
    }
    public static IEnumerable<object[]> CodecEvents()
    {
        using var vectors = Vectors();
        foreach (var item in vectors.RootElement.GetProperty("events").EnumerateArray()) yield return [item.Clone()];
        foreach (var item in vectors.RootElement.GetProperty("comparison_variants").EnumerateArray()) yield return [item.Clone()];
    }
    [Theory]
    [MemberData(nameof(CodecEvents))]
    public void Accepted_literal_intent_and_binding_vectors_pin_every_byte(JsonElement vector)
    {
        var entry = vector.GetProperty("entry");
        var row = Row(entry);
        var temporal = Evidence(entry.GetProperty("Temporal"));
        var request = vector.GetProperty("request");
        var intent = RecordTemporalJournalBinding.EncodeIntent(request.GetProperty("tenant").GetString()!, row.RecordTypeId,
            (RecordTemporalCommandKind)request.GetProperty("kind").GetInt32(), request.GetProperty("target").GetString(),
            temporal.Predecessor, Date(request.GetProperty("from").GetString()!),
            request.GetProperty("to").ValueKind == JsonValueKind.Null ? null : Date(request.GetProperty("to").GetString()!),
            request.GetProperty("reason").GetString(), row.RequestedVersion, JsonNode.Parse(row.Body.Span)!.AsObject());
        Assert.Equal(vector.GetProperty("legacy_component_hex").GetString(), Convert.ToHexStringLower(RecordWriteIntent.Encode(
            row.RecordTypeId, row.RequestedVersion, JsonNode.Parse(row.Body.Span)!.AsObject())));
        Assert.Equal(vector.GetProperty("intent_hex").GetString(), Convert.ToHexStringLower(intent));
        Assert.Equal(vector.GetProperty("intent_sha256").GetString(), Convert.ToHexStringLower(SHA256.HashData(intent)));
        Assert.Equal(vector.GetProperty("publication_binding_hex").GetString(), Convert.ToHexStringLower(RecordWriteJournalBinding.Encode(row)));
        var operation = entry.GetProperty("Operation");
        var identity = new KernelOperationIdentity(operation.GetProperty("CommandId").GetString()!,
            operation.GetProperty("IdempotencyKey").GetString()!, operation.GetProperty("Fingerprint").GetString()!);
        var binding = RecordTemporalJournalBinding.EncodeBinding(entry.GetProperty("Key").GetString()!, identity, row, Audit(entry), temporal);
        Assert.Equal(vector.GetProperty("temporal_binding_hex").GetString(), Convert.ToHexStringLower(binding));
        Assert.Equal(vector.GetProperty("temporal_binding_sha256").GetString(),
            RecordTemporalJournalBinding.HashBinding(entry.GetProperty("Key").GetString()!, identity, row, Audit(entry), temporal));
    }
    public static IEnumerable<object[]> NegativeJournals()
    {
        using var vectors = Vectors();
        foreach (var item in vectors.RootElement.GetProperty("negative_journals").EnumerateArray())
            yield return [item.GetProperty("id").GetString()!, item.GetProperty("utf8_hex").GetString()!];
    }
    private static async Task RefusesAllRoutes(byte[] bytes)
    {
        using var path = new JournalPath();
        for (var route = 0; route < 9; route++)
        {
            File.WriteAllText(path.FileName, RecordWriteJournalBindingTests.BaseJournal().ToJsonString());
            var clock = new Clock(Date("2031-06-03T09:00:02+00:00"));
            var store = new FileJournalRecordWriteStore(path.FileName, clock);
            File.WriteAllBytes(path.FileName, bytes);
            async Task Act()
            {
                switch (route)
                {
                    case 0: _ = new FileJournalRecordWriteStore(path.FileName); break;
                    case 1: _ = await store.FindAsync(new RecordWriteOperationKey("acme", "alice", "op-ordinary")); break;
                    case 2: _ = await store.FindAsync("acme", "rec-ordinary"); break;
                    case 3: _ = await AppendOrdinary(store, RecordWriteJournalBindingTests.Row("unrelated-new", "unrelated-new")); break;
                    case 4: _ = await store.FindTemporalOperationAsync(new("acme", "alice", "op-r1")); break;
                    case 5: _ = await store.FindAtAsync("acme", "rec-ordinary", Date("2031-05-15T00:00:00-04:00")); break;
                    case 6: _ = await store.HistoryAsync("acme", "rec-ordinary"); break;
                    case 7: _ = await store.FindTemporalTargetAsync("acme", "rec-ordinary"); break;
                    case 8: _ = await AppendTemporal(store, Event("r1")); break;
                }
            }
            var error = await Assert.ThrowsAsync<InvalidDataException>(Act);
            Assert.Equal("Records journal is invalid.", error.Message);
            Assert.Null(error.InnerException);
            Assert.Equal(bytes, File.ReadAllBytes(path.FileName));
            Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp"));
        }
    }

    [Theory]
    [MemberData(nameof(NegativeJournals))]
    public async Task Corruption_anywhere_refuses_every_load_before_any_result(string id, string hex)
    {
        Assert.False(string.IsNullOrEmpty(id));
        await RefusesAllRoutes(Convert.FromHexString(hex));
    }

