    [Fact]
    public async Task Every_receipt_field_and_operation_audit_association_is_checked()
    {
        using var vectors = Vectors();
        var receipts = vectors.RootElement.GetProperty("negative_journals").EnumerateArray()
            .Where(value => value.GetProperty("id").GetString()!.StartsWith("receipt-", StringComparison.Ordinal)).ToArray();
        Assert.Equal(new[] { "receipt-RecordId", "receipt-OperationId", "receipt-RecordTypeId", "receipt-Version",
            "receipt-DefinitionDigest", "receipt-Schema", "receipt-RecordedAt" }, receipts.Select(value => value.GetProperty("id").GetString()));
        foreach (var item in receipts) await RefusesAllRoutes(Convert.FromHexString(item.GetProperty("utf8_hex").GetString()!));
        Assert.Equal("a1462eba94b9c7726fe9608c89485091538f5afb77961e0210191a3a0569ea5b",
            ReferenceHash(JsonNode.Parse(Event("r1").GetProperty("entry").GetRawText())!.AsObject()));
        foreach (var association in new[] { "command", "fingerprint", "actor", "time", "origin" })
        {
            var root = JsonNode.Parse(Mixed("M2-temporal-introduces-3"))!.AsObject();
            var entry = root["Entries"]![2]!.AsObject();
            if (association == "command") entry["Operation"]!["CommandId"] = "other-record";
            if (association == "fingerprint") entry["Operation"]!["Fingerprint"] = new string('a', 64);
            if (association == "actor") entry["Audit"]!["ActorId"] = "bobby";
            if (association == "time") entry["Audit"]!["RecordedAt"] = "2031-06-03T10:00:00+01:00";
            if (association == "origin") entry["Audit"]!["OriginatorId"] = "originator";
            entry["TemporalBinding"]!["Hash"] = ReferenceHash(entry);
            await RefusesAllRoutes(Encoding.UTF8.GetBytes(root.ToJsonString()));
        }
    }

    [Fact]
    public async Task Temporal_binding_covers_exact_body_and_authority_bytes()
    {
        using var vectors = Vectors();
        foreach (var id in new[] { "body-hash", "authority-time-hash", "authority-snapshot-hash" })
        {
            var item = vectors.RootElement.GetProperty("negative_journals").EnumerateArray()
                .Single(value => value.GetProperty("id").GetString() == id);
            await RefusesAllRoutes(Convert.FromHexString(item.GetProperty("utf8_hex").GetString()!));
        }
        var r1 = Event("r1");
