        Assert.Equal(r1.GetProperty("intent_sha256").GetString(), numeric.GetProperty("intent_sha256").GetString());
        Assert.NotEqual(r1.GetProperty("temporal_binding_sha256").GetString(), numeric.GetProperty("temporal_binding_sha256").GetString());
    }

    [Fact]
    public async Task Closed_decoded_members_and_valid_scalar_conversion_are_enforced()
    {
        using var vectors = Vectors();
        foreach (var id in new[] { "duplicate-unescaped-root", "unknown-temporal-member", "missing-temporal-reason",
            "utf8-bom", "invalid-utf8", "count-tag-disagreement", "unknown-format" })
        {
            var item = vectors.RootElement.GetProperty("negative_journals").EnumerateArray().Single(value => value.GetProperty("id").GetString() == id);
            await RefusesAllRoutes(Convert.FromHexString(item.GetProperty("utf8_hex").GetString()!));
        }
        foreach (var alias in new[] { "\"Revision\":1,\"\\u0052evision\":1", "\"Revision\":1,\"revision\":1" })
        {
            var source = Encoding.UTF8.GetString(Mixed("M2-temporal-introduces-3"));
            var bytes = Encoding.UTF8.GetBytes(source.Replace("\"Temporal\":{\"Revision\":1", "\"Temporal\":{" + alias, StringComparison.Ordinal));
            Assert.NotEqual(source, Encoding.UTF8.GetString(bytes));
            await RefusesAllRoutes(bytes);
        }
    }

    [Fact]
    public async Task New_owned_objects_reject_each_missing_null_unknown_and_decoded_duplicate_member()
    {
        var baseline = Mixed("M5-temporal-after-ordinary-accepted");
        Assert.Equal("a556b88371da4ed9c69d3e238db5a80473b07931fdd6292910ec825772a49983",
            Convert.ToHexStringLower(SHA256.HashData(baseline)));
        using var path = new JournalPath();
        // A clean complete input exercises the same nine actual dispatches before any one-field mutation.
        for (var route = 0; route < 9; route++)
        {
            File.WriteAllBytes(path.FileName, baseline);
            var store = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt));
            switch (route)
            {
                case 0: _ = new FileJournalRecordWriteStore(path.FileName); break;
                case 1: _ = await store.FindAsync(new RecordWriteOperationKey("acme", "alice", "op-ordinary")); break;
                case 2: _ = await store.FindAsync("acme", "rec-ordinary"); break;
                case 3: Assert.Equal(RecordWriteCommitDisposition.Created,
                    (await AppendOrdinary(store, RecordWriteJournalBindingTests.Row("unrelated-new", "unrelated-new"))).Disposition); break;
                case 4: Assert.NotNull(await store.FindTemporalOperationAsync(new("acme", "alice", "op-r1"))); break;
                case 5: Assert.Equal(RecordTemporalLookupKind.NonTemporal,
                    (await store.FindAtAsync("acme", "rec-ordinary", GateAt)).Kind); break;
                case 6: Assert.Equal(RecordTemporalHistoryKind.NonTemporal,
                    (await store.HistoryAsync("acme", "rec-ordinary")).Kind); break;
                case 7: Assert.NotNull(await store.FindTemporalTargetAsync("acme", "rec-ordinary")); break;
                case 8: Assert.Equal(RecordTemporalCommitDisposition.Replayed,
                    (await AppendTemporal(store, Event("r1"))).Disposition); break;
            }
            Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp"));
            if (route != 3) Assert.Equal(baseline, File.ReadAllBytes(path.FileName));
        }
        var declarations = new (string Object, string[] Members, string[] Nullable)[]
        {
            ("root", ["Format", "LegacyEntryCount", "Entries"], []),
            ("entry", ["Tag", "Key", "Operation", "Row", "Audit", "Receipt", "Binding", "Temporal", "TemporalBinding"], []),
            ("operation", ["CommandId", "IdempotencyKey", "Fingerprint"], []),
            ("row", ["Tenant", "RecordId", "RecordTypeId", "Version", "DefinitionDigest", "Schema", "ActorId", "OperationId",
                "RequestedVersion", "IntentEncodingVersion", "IntentDigest", "Body", "RecordedAt", "OriginatorId",
                "AcceptedCommandId", "AcceptanceAuditId", "PublicationVersionId"],
                ["RequestedVersion", "OriginatorId", "AcceptedCommandId", "AcceptanceAuditId"]),
            ("audit", ["AuditId", "ActorId", "RecordedAt", "Payload", "AuthoritySnapshot", "OriginatorId"], ["OriginatorId"]),
            ("receipt", ["RecordId", "OperationId", "RecordTypeId", "Version", "DefinitionDigest", "Schema", "RecordedAt"], []),
            ("publication-binding", ["Encoding", "Hash"], []),
            ("temporal", ["Revision", "Predecessor", "Supersedes", "EffectiveFrom", "EffectiveTo", "Reason", "AuthorityRecordedAt"], ["EffectiveTo"]),
            ("predecessor", ["Revision", "Hash"], []),
            ("segment", ["Revision", "EffectiveFrom", "EffectiveTo"], ["EffectiveTo"]),
            ("segment-basis", ["Revision", "Hash"], []),
            ("binding", ["Encoding", "Hash"], []),
        };
        foreach (var declaration in declarations)
        {
            var unknownRoot = JsonNode.Parse(baseline)!.AsObject();
            Owned(unknownRoot, declaration.Object)["unknown-owned-member"] = 7;
            // Unknown/duplicate names do not change any field used by the existing valid reference hash.
            await RefusesAllRoutes(Encoding.UTF8.GetBytes(unknownRoot.ToJsonString()));
            foreach (var member in declaration.Members)
            {
                var missing = JsonNode.Parse(baseline)!.AsObject();
                Assert.True(Owned(missing, declaration.Object).Remove(member));
                await RefusesAllRoutes(Encoding.UTF8.GetBytes(missing.ToJsonString()));
                if (!declaration.Nullable.Contains(member, StringComparer.Ordinal))
                {
                    var nullRoot = JsonNode.Parse(baseline)!.AsObject();
                    Owned(nullRoot, declaration.Object)[member] = null;
                    await RefusesAllRoutes(Encoding.UTF8.GetBytes(nullRoot.ToJsonString()));
                }
                var duplicate = JsonNode.Parse(baseline)!.AsObject();
                var target = Owned(duplicate, declaration.Object);
                var originalValue = target[member]?.ToJsonString() ?? "null";
                target["__duplicate_member_marker__"] = 1;
                var alias = "\\u" + ((int)member[0]).ToString("x4", CultureInfo.InvariantCulture) + member[1..];
                var duplicateText = duplicate.ToJsonString().Replace("\"__duplicate_member_marker__\":1",
                    "\"" + alias + "\":" + originalValue, StringComparison.Ordinal);
                Assert.DoesNotContain("__duplicate_member_marker__", duplicateText, StringComparison.Ordinal);
                await RefusesAllRoutes(Encoding.UTF8.GetBytes(duplicateText));
            }
        }
        static JsonObject Owned(JsonObject root, string kind)
        {
            var temporalEntry = root["Entries"]!.AsArray()[^1]!.AsObject();
            var temporal = temporalEntry["Temporal"]!.AsObject();
            return kind switch
            {
                "root" => root,
                "entry" => temporalEntry,
                "operation" => temporalEntry["Operation"]!.AsObject(),
                "row" => temporalEntry["Row"]!.AsObject(),
                "audit" => temporalEntry["Audit"]!.AsObject(),
                "receipt" => temporalEntry["Receipt"]!.AsObject(),
                "publication-binding" => temporalEntry["Binding"]!.AsObject(),
                "temporal" => temporal,
                "predecessor" => temporal["Predecessor"]!.AsObject(),
                "segment" => temporal["Supersedes"]![0]!.AsObject(),
                "segment-basis" => temporal["Supersedes"]![0]!["Revision"]!.AsObject(),
                "binding" => temporalEntry["TemporalBinding"]!.AsObject(),
                _ => throw new ArgumentOutOfRangeException(nameof(kind)),
            };
        }
    }
    [Fact]
    public async Task Rehashed_amendment_requires_nonblank_reason()
    {
        // P is accepted r2 literal data, not r1's different publication and not candidate Encode output.
        var publication = Event("r2").GetProperty("publication_binding_hex").GetString()!;
        var clean = JsonNode.Parse(Event("r2").GetProperty("entry").GetRawText())!.AsObject();
        Assert.Equal("c2dddc2baabb6a3e3fe8c8007166cbbe0da9aa1cab6a7d04a995face728b8f1b",
            ReferenceHash(clean, publication));
        foreach (var reason in new string?[] { null, "", " ", "\u00a0", "\u3000" })
        {
            var root = JsonNode.Parse(Mixed("M5-temporal-after-ordinary-accepted"))!.AsObject();
            var last = root["Entries"]!.AsArray()[^1]!.AsObject();
            Assert.Equal("op-r2", last["Row"]!["OperationId"]!.GetValue<string>());
            last["Temporal"]!["Reason"] = reason;
            last["TemporalBinding"]!["Hash"] = ReferenceHash(last, publication);
            await RefusesAllRoutes(Encoding.UTF8.GetBytes(root.ToJsonString()));
        }
    }

    [Fact]
    public async Task Concurrent_same_basis_has_one_winner_without_timestamp_order()
    {
        using var fixture = await Fixture.Create();
        var first = Committed(await fixture.CreateEvent());
        fixture.AuthorityClock.Now = GateAt.AddDays(-1);
        var arrivals = 0;
        var bothPrepared = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        fixture.Storage.BeforeCommit = async () =>
        {
            if (Interlocked.Increment(ref arrivals) == 2) bothPrepared.SetResult();
            await bothPrepared.Task.WaitAsync(TimeSpan.FromSeconds(15));
        };
        var competing = await Task.WhenAll(fixture.AmendEvent(first, "candidate-a", value: 20),
            fixture.AmendEvent(first, "candidate-b", value: 30));
        Assert.Equal(2, arrivals);
        Assert.Equal(1, competing.Count(value => value.Status == RecordTemporalWriteStatus.Created));
        Assert.Equal(1, competing.Count(value => value.Status == RecordTemporalWriteStatus.BasisMismatch));
        var winner = Assert.Single(competing, value => value.Status == RecordTemporalWriteStatus.Created).Receipt!;
        Assert.Equal(2, winner.Temporal.Revision);
        Assert.True(winner.Temporal.AuthorityRecordedAt < first.Temporal.AuthorityRecordedAt);
        Assert.Equal(2, fixture.AuthorityClock.Reads);
        var history = await new FileJournalRecordWriteStore(fixture.PathName).HistoryAsync(Tenant, first.Receipt.RecordId);
        Assert.Equal(new[] { 1L, 2L }, history.Versions.Select(value => value.Temporal.Revision));
        Assert.Equal(2, fixture.Entries());
        using var committed = JsonDocument.Parse(fixture.Bytes());
        Assert.Equal(2, committed.RootElement.GetProperty("Entries").EnumerateArray()
            .Select(value => value.GetProperty("Audit").GetProperty("AuditId").GetString()).Distinct().Count());
        Assert.Equal(2, committed.RootElement.GetProperty("Entries").EnumerateArray()
            .Select(value => value.GetProperty("Receipt").GetProperty("OperationId").GetString()).Distinct().Count());
        Assert.Equal(new RecordTemporalBasis(1, first.BindingHash), history.Versions[1].Temporal.Predecessor);
    }

    [Fact]
    public async Task Locked_replay_recheck_precedes_basis_fence_and_stamp()
    {
        using var path = new JournalPath();
        var before = Mixed("M5-temporal-after-ordinary-accepted");
        File.WriteAllBytes(path.FileName, before);
        var clockless = new FileJournalRecordWriteStore(path.FileName);
        Assert.False(clockless.HasAuthorityClock);
        var replay = await AppendTemporal(clockless, Event("r2"));
        Assert.Equal(RecordTemporalCommitDisposition.Replayed, replay.Disposition);
        Assert.Null(replay.Receipt);
        Assert.Equal("c2dddc2baabb6a3e3fe8c8007166cbbe0da9aa1cab6a7d04a995face728b8f1b", replay.Stored!.Receipt!.BindingHash);
        OriginalReceipt(Event("r2").GetProperty("entry").GetProperty("Receipt"), replay.Stored.Receipt.Receipt);
        Assert.Equal(before, File.ReadAllBytes(path.FileName));
        var freshMint = JsonNode.Parse(Event("r1").GetRawText())!.AsObject();
        freshMint["entry"]!["Row"]!["RecordId"] = "different-server-mint";
        freshMint["entry"]!["Operation"]!["CommandId"] = "different-server-mint";
        using var retry = JsonDocument.Parse(freshMint.ToJsonString());
        var original = await AppendTemporal(clockless, retry.RootElement);
        Assert.Equal(RecordTemporalCommitDisposition.Replayed, original.Disposition);
        Assert.Equal("rec-001", original.Stored!.Receipt!.Receipt.RecordId);
        Assert.Equal("a1462eba94b9c7726fe9608c89485091538f5afb77961e0210191a3a0569ea5b", original.Stored.Receipt.BindingHash);
        Assert.Equal(before, File.ReadAllBytes(path.FileName));
    }

    [Fact]
