    [Fact]
    public async Task Mixed_legacy_bound_temporal_ordinary_accepted_append_preserves_every_span()
    {
        using var path = new JournalPath();
        var fixture = RecordWriteJournalBindingTests.Fixture("Q31/journal/records.json");
        var original = File.ReadAllBytes(fixture);
        File.WriteAllBytes(path.FileName, original);
        using var old = JsonDocument.Parse(original);
        var oldEntries = old.RootElement.GetProperty("Entries").EnumerateArray().Select(value => value.Clone()).ToArray();
        Assert.Equal(4, oldEntries.Length);
        Assert.DoesNotContain(oldEntries, entry => entry.GetProperty("Row").GetProperty("RecordId").GetString() == "rec-001");
        var clock = new Clock(Evidence(Event("r1").GetProperty("entry").GetProperty("Temporal")).AuthorityRecordedAt);
        var store = new FileJournalRecordWriteStore(path.FileName, clock);
        foreach (var entry in oldEntries)
        {
            var row = Row(entry);
            OriginalReceipt(entry.GetProperty("Receipt"), (await store.FindAsync(OriginalKey(row)))!.Receipt);
        }
        Assert.Equal(original, File.ReadAllBytes(path.FileName));
        var ordinary = RecordWriteJournalBindingTests.Row("ordinary-new", "ordinary-new");
        Assert.Equal(RecordWriteCommitDisposition.Created, (await AppendOrdinary(store, ordinary)).Disposition);
        var first = await AppendTemporal(store, Event("r1"));
        Assert.Equal(RecordTemporalCommitDisposition.Created, first.Disposition);
        Assert.Equal("a1462eba94b9c7726fe9608c89485091538f5afb77961e0210191a3a0569ea5b", first.Receipt!.BindingHash);
        var beforeLater = File.ReadAllBytes(path.FileName);
        using var prefix = JsonDocument.Parse(beforeLater, new JsonDocumentOptions { MaxDepth = 65 });
        var prefixSpans = prefix.RootElement.GetProperty("Entries").EnumerateArray().Select(value => value.GetRawText()).ToArray();
        Assert.Equal(RecordWriteCommitDisposition.Created,
            (await AppendOrdinary(store, RecordWriteJournalBindingTests.Row("ordinary-after", "ordinary-after"))).Disposition);
        var accepted = RecordWriteJournalBindingTests.Row("accepted-after", "op-r1") with
        { ActorId = "worker", OriginatorId = "alice", AcceptedCommandId = "command", AcceptanceAuditId = "acceptance" };
        var acceptedKey = new RecordWriteOperationKey("acme", "alice", "op-r1") { Origin = "accepted-command" };
        Assert.Equal(RecordWriteCommitDisposition.Created, (await AppendOrdinary(store, accepted, acceptedKey)).Disposition);
        clock.Now = Evidence(Event("r2").GetProperty("entry").GetProperty("Temporal")).AuthorityRecordedAt;
        var next = await AppendTemporal(store, Event("r2"));
        Assert.Equal("c2dddc2baabb6a3e3fe8c8007166cbbe0da9aa1cab6a7d04a995face728b8f1b", next.Receipt!.BindingHash);
        var reopened = new FileJournalRecordWriteStore(path.FileName);
        using var final = JsonDocument.Parse(File.ReadAllBytes(path.FileName), new JsonDocumentOptions { MaxDepth = 65 });
        Assert.Equal("records-write-file-journal/3", final.RootElement.GetProperty("Format").GetString());
        Assert.Equal(4, final.RootElement.GetProperty("LegacyEntryCount").GetInt32());
        var entries = final.RootElement.GetProperty("Entries").EnumerateArray().ToArray();
        Assert.Equal(9, entries.Length);
        for (var i = 0; i < oldEntries.Length; i++)
        {
            Assert.Equal(Encoding.UTF8.GetBytes(oldEntries[i].GetRawText()),
                Encoding.UTF8.GetBytes(entries[i].GetProperty("Legacy").GetRawText()));
            var row = Row(oldEntries[i]);
            var key = OriginalKey(row);
            OriginalReceipt(oldEntries[i].GetProperty("Receipt"), (await reopened.FindAsync(key))!.Receipt);
            var replay = await AppendOrdinary(reopened, row with { PublicationVersionId = row.Version }, key);
            Assert.Equal(RecordWriteCommitDisposition.Replayed, replay.Disposition);
            OriginalReceipt(oldEntries[i].GetProperty("Receipt"), replay.Receipt);
        }
        for (var i = 0; i < prefixSpans.Length; i++) Assert.Equal(prefixSpans[i], entries[i].GetRawText());
        Assert.Equal(new[] { 1L, 2L }, (await reopened.HistoryAsync("acme", "rec-001")).Versions.Select(value => value.Temporal.Revision));
        Assert.Equal("accepted-after", (await reopened.FindAsync(acceptedKey))!.Receipt!.RecordId);
        Assert.Equal(original, File.ReadAllBytes(fixture));
        using var vectors = Vectors();
        foreach (var supplied in vectors.RootElement.GetProperty("mixed_journals").EnumerateArray())
        {
            var bytes = Convert.FromHexString(supplied.GetProperty("utf8_hex").GetString()!);
            Assert.Equal(supplied.GetProperty("sha256").GetString(), Convert.ToHexStringLower(SHA256.HashData(bytes)));
            File.WriteAllBytes(path.FileName, bytes);
            var acceptedInput = new FileJournalRecordWriteStore(path.FileName, clock);
            _ = await acceptedInput.FindAtAsync("acme", "rec-ordinary", AuthorityAt);
            var before = File.ReadAllBytes(path.FileName);
            Assert.Equal(RecordWriteCommitDisposition.Created,
                (await AppendOrdinary(acceptedInput, RecordWriteJournalBindingTests.Row("literal-mixed-new", "literal-mixed-new"))).Disposition);
            using var input = JsonDocument.Parse(before);
            using var output = JsonDocument.Parse(File.ReadAllBytes(path.FileName));
            Assert.Equal(supplied.GetProperty("id").GetString() == "M0-original-1" ? "records-write-file-journal/2"
                : input.RootElement.GetProperty("Format").GetString(), output.RootElement.GetProperty("Format").GetString());
            var previous = input.RootElement.GetProperty("Entries").EnumerateArray().ToArray();
            Assert.Equal(previous.Length + 1, output.RootElement.GetProperty("Entries").GetArrayLength());
            for (var i = 0; i < previous.Length; i++)
                Assert.Equal(previous[i].GetRawText(), (supplied.GetProperty("id").GetString() == "M0-original-1"
                    ? output.RootElement.GetProperty("Entries")[i].GetProperty("Legacy")
                    : output.RootElement.GetProperty("Entries")[i]).GetRawText());
        }
    }

    [Fact]
    public async Task Open_read_replay_and_conflict_do_not_convert()
    {
        using var path = new JournalPath();
        using var vectors = Vectors();
        foreach (var supplied in vectors.RootElement.GetProperty("mixed_journals").EnumerateArray())
        {
            var before = Convert.FromHexString(supplied.GetProperty("utf8_hex").GetString()!);
            File.WriteAllBytes(path.FileName, before);
            var store = new FileJournalRecordWriteStore(path.FileName);
            using var input = JsonDocument.Parse(before);
            var first = input.RootElement.GetProperty("Entries")[0];
            if (input.RootElement.GetProperty("Format").GetString() != "records-write-file-journal/1") first = first.GetProperty("Legacy");
            var row = Row(first);
            OriginalReceipt(first.GetProperty("Receipt"), (await store.FindAsync(OriginalKey(row)))!.Receipt);
            Assert.Equal(RecordTemporalLookupKind.NonTemporal, (await store.FindAtAsync(row.Tenant, row.RecordId, GateAt)).Kind);
            Assert.Equal(RecordTemporalHistoryKind.NonTemporal, (await store.HistoryAsync(row.Tenant, row.RecordId)).Kind);
            var replay = await AppendOrdinary(store, row with { PublicationVersionId = row.Version }, OriginalKey(row));
            Assert.Equal(RecordWriteCommitDisposition.Replayed, replay.Disposition);
            OriginalReceipt(first.GetProperty("Receipt"), replay.Receipt);
            var conflict = await AppendOrdinary(store, row with { PublicationVersionId = row.Version, IntentDigest = new string('a', 64) }, OriginalKey(row));
            Assert.Equal(RecordWriteCommitDisposition.Conflict, conflict.Disposition);
            OriginalReceipt(first.GetProperty("Receipt"), conflict.Receipt);
            Assert.Equal(before, File.ReadAllBytes(path.FileName));
        }
    }

    private static byte[] PaddedUnion(int length, string mixed = "M2-temporal-introduces-3")
    {
        var root = JsonNode.Parse(Mixed(mixed))!.AsObject();
        var legacy = root["Entries"]![0]!["Legacy"]!.AsObject();
        legacy["Padding"] = "";
        var prefix = Encoding.UTF8.GetBytes(root.ToJsonString());
        Assert.True(length >= prefix.Length);
        legacy["Padding"] = new string('p', length - prefix.Length);
        var bytes = Encoding.UTF8.GetBytes(root.ToJsonString());
        Assert.Equal(length, bytes.Length);
        return bytes;
    }

    [Fact]
    public async Task Current_and_temporal_reads_share_real_sixteen_MiB_spine()
    {
        using var path = new JournalPath();
        var exact = PaddedUnion(16 * 1024 * 1024);
        File.WriteAllBytes(path.FileName, exact);
        long observed = 0;
        var store = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt), count => observed = count, null);
        Assert.Equal(RecordTemporalLookupKind.NonTemporal, (await store.FindAtAsync("acme", "rec-ordinary", AuthorityAt)).Kind);
        Assert.Equal(16 * 1024 * 1024L, observed);
        Assert.NotNull(await store.FindAsync("acme", "rec-ordinary"));
        Assert.Equal(RecordTemporalHistoryKind.Temporal, (await store.HistoryAsync("acme", "rec-001")).Kind);
        Assert.True((await store.FindTemporalTargetAsync("acme", "rec-001"))!.IsTemporal);
        Assert.Equal(exact, File.ReadAllBytes(path.FileName));
        var lateCorruption = exact.ToArray(); lateCorruption[^1] = (byte)'!';
        File.WriteAllBytes(path.FileName, lateCorruption); observed = 0;
        await Assert.ThrowsAsync<InvalidDataException>(() => store.FindAtAsync("acme", "rec-ordinary", AuthorityAt).AsTask());
        Assert.Equal(16 * 1024 * 1024L, observed);
        Assert.Equal(lateCorruption, File.ReadAllBytes(path.FileName));
        var over = PaddedUnion(16 * 1024 * 1024 + 1);
        File.WriteAllBytes(path.FileName, over);
        await Assert.ThrowsAsync<InvalidDataException>(() => store.FindAsync("acme", "rec-ordinary").AsTask());
        await Assert.ThrowsAsync<InvalidDataException>(() => store.FindAtAsync("acme", "rec-001", AuthorityAt).AsTask());
        await Assert.ThrowsAsync<InvalidDataException>(() => store.HistoryAsync("acme", "rec-001").AsTask());
        await Assert.ThrowsAsync<InvalidDataException>(() => store.FindTemporalTargetAsync("acme", "rec-001").AsTask());
        var uncapped = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt));
        Assert.NotNull(await uncapped.FindAsync(new RecordWriteOperationKey("acme", "alice", "op-ordinary")));
        Assert.Equal(RecordWriteCommitDisposition.Created,
            (await AppendOrdinary(uncapped, RecordWriteJournalBindingTests.Row("large-ordinary", "large-ordinary"))).Disposition);
        Assert.True(new FileInfo(path.FileName).Length > 16 * 1024 * 1024);
        using var fixture = await Fixture.Create();
        File.WriteAllBytes(fixture.PathName, PaddedUnion(16 * 1024 * 1024 + 1, "M5-temporal-after-ordinary-accepted"));
        var r2 = Event("r2").GetProperty("entry");
        var row = Row(r2); var temporal = Evidence(r2.GetProperty("Temporal"));
        await Assert.ThrowsAsync<InvalidDataException>(() => fixture.Writer.AmendAsync(new("acme", "alice"),
            new("rec-001", "op-r2", temporal.Predecessor!, JsonNode.Parse(row.Body.Span)!.AsObject(),
                temporal.EffectiveFrom, temporal.EffectiveTo, temporal.Reason!)).AsTask());
        Assert.Empty(fixture.Access.Requests);
        Assert.Equal(0, fixture.Storage.ReceiptLookups);

        var shortInput = PaddedUnion(16 * 1024 * 1024 - 81920);
        File.WriteAllBytes(path.FileName, shortInput);
        var added = Encoding.ASCII.GetBytes(new string(' ', 81921));
        var expectedGrown = shortInput.Concat(added).ToArray();
        var grew = false; observed = 0;
        var growing = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt), count =>
        {
            observed = count;
            if (grew) return;
            grew = true;
            Assert.True(count > 0 && count < shortInput.Length);
            using var append = new FileStream(path.FileName, FileMode.Append, FileAccess.Write, FileShare.ReadWrite);
            append.Write(added);
        }, null);
        // This real file-sharing witness is not skipped or represented as executed on an unqualified platform.
        await Assert.ThrowsAsync<InvalidDataException>(() => growing.HistoryAsync("acme", "rec-001").AsTask());
        Assert.True(grew);
        Assert.Equal(16 * 1024 * 1024L + 1, observed);
        Assert.Equal(expectedGrown, File.ReadAllBytes(path.FileName));
    }

    private static byte[] DeepLegacy(int arrays)
    {
        var original = File.ReadAllBytes(RecordWriteJournalBindingTests.Fixture("Q31/journal/records.json"));
        using var document = JsonDocument.Parse(original);
        var spans = document.RootElement.GetProperty("Entries").EnumerateArray().Select(value => value.GetRawText()).ToArray();
        spans[0] = spans[0][..^1] + ",\"Depth\":" + new string('[', arrays) + "0" + new string(']', arrays) + "}";
        return Encoding.UTF8.GetBytes("{\"Format\":\"records-write-file-journal/1\",\"Entries\":[" + string.Join(",", spans) + "]}");
    }

    private static byte[] DeepThree(int arrays)
    {
        using var document = JsonDocument.Parse(Mixed("M2-temporal-introduces-3"));
        var spans = document.RootElement.GetProperty("Entries").EnumerateArray().Select(value => value.GetRawText()).ToArray();
        var legacy = document.RootElement.GetProperty("Entries")[0].GetProperty("Legacy").GetRawText();
        legacy = legacy[..^1] + ",\"Depth\":" + new string('[', arrays) + "0" + new string(']', arrays) + "}";
        spans[0] = "{\"Tag\":\"legacy/1\",\"Legacy\":" + legacy + "}";
        return Encoding.UTF8.GetBytes("{\"Format\":\"records-write-file-journal/3\",\"LegacyEntryCount\":1,\"Entries\":[" + string.Join(",", spans) + "]}");
    }

