            (await AppendOrdinary(independent65, RecordWriteJournalBindingTests.Row("boundary-new", "boundary-new"))).Disposition);
        _ = new FileJournalRecordWriteStore(path.FileName);
        await RefusesAllRoutes(DeepLegacy(62));
        await RefusesAllRoutes(DeepThree(62));
        // Invalid union construction is refused before publication, separately from invalid input-load witnesses.
        File.WriteAllBytes(path.FileName, Mixed("M2-temporal-introduces-3"));
        var validOpened = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt), null, () => reached++);
        var before = File.ReadAllBytes(path.FileName); reached = 0;
        var collision = RecordWriteJournalBindingTests.Row("rec-001", "collision-after-stage");
        await Assert.ThrowsAsync<InvalidOperationException>(() => AppendOrdinary(validOpened, collision));
