        Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp"));
    }

    [Fact]
    public async Task Cancellation_during_real_progress_and_before_replace_preserves_token()
    {
        using var path = new JournalPath();
        var bytes = PaddedUnion(1048576);
        File.WriteAllBytes(path.FileName, bytes);
        using var cancellation = new CancellationTokenSource();
        long first = 0;
        var reading = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt), count =>
        {
            if (first != 0) return;
            first = count;
            Assert.True(0 < count && count < bytes.Length);
            cancellation.Cancel();
        }, null);
        var readError = await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            reading.HistoryAsync("acme", "rec-001", cancellation.Token).AsTask());
        Assert.Equal(cancellation.Token, readError.CancellationToken);
        Assert.True(first > 0);
        Assert.Equal(bytes, File.ReadAllBytes(path.FileName));
        Assert.Equal(RecordTemporalHistoryKind.Temporal, (await reading.HistoryAsync("acme", "rec-001")).Kind);
        using var beforeMove = new CancellationTokenSource();
        File.WriteAllBytes(path.FileName, Mixed("M1-ordinary-converts-to-2"));
        var before = File.ReadAllBytes(path.FileName);
        var reached = 0;
        var writing = new FileJournalRecordWriteStore(path.FileName, new Clock(
            Evidence(Event("r1").GetProperty("entry").GetProperty("Temporal")).AuthorityRecordedAt), null,
            () => { reached++; beforeMove.Cancel(); });
        var writeError = await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            AppendTemporal(writing, Event("r1"), beforeMove.Token));
        Assert.Equal(beforeMove.Token, writeError.CancellationToken);
        Assert.Equal(1, reached);
        Assert.Equal(before, File.ReadAllBytes(path.FileName));
        Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp"));
        _ = new FileJournalRecordWriteStore(path.FileName);
        using var fixture = await Fixture.Create();
        using var stagedCancellation = new CancellationTokenSource();
        fixture.Storage.OnStep = step => { if (step == "record") stagedCancellation.Cancel(); };
        var stagedError = await Assert.ThrowsAnyAsync<OperationCanceledException>(() => fixture.Writer.CreateEffectiveAsync(
            new(Tenant, Actor), new(RecordTemporalWriteOperationTests.Type, "stage-cancel", Body(), GateAt, null), stagedCancellation.Token).AsTask());
        Assert.Equal(stagedCancellation.Token, stagedError.CancellationToken);
        Assert.Contains("operation", fixture.Storage.Events);
        Assert.Contains("rollback", fixture.Storage.Events);
        Assert.Equal(0, fixture.AuthorityClock.Reads);
        Assert.False(File.Exists(fixture.PathName));
    }

