            Assert.Same(fault, await Assert.ThrowsAsync<IOException>(() => fixture.CreateEvent()));
            Assert.False(File.Exists(fixture.PathName));
            Assert.Empty(Directory.GetFiles(fixture.DirectoryName, "*.tmp"));
            if (stage != "begin") Assert.Contains("rollback", fixture.Storage.Events);
        }
        using (var fixture = await Fixture.Create())
        {
            var joinedFault = new IOException("joined-participant");
            fixture.Schemas.DuringValidate = async token =>
            {
                try
                {
                    await KernelTransactionBoundary.JoinAsync(new KernelCommand<string>(new("joined", "joined", "joined"), "record",
                        new("joined-audit", Actor, GateAt, ReadOnlyMemory<byte>.Empty)), new FailedJoin(joinedFault), token);
                }
                catch (IOException error) { Assert.Same(joinedFault, error); }
            };
            var error = await Assert.ThrowsAsync<KernelTransactionStateException>(() => fixture.CreateEvent());
            Assert.Equal("kernel.enclosing-execution-doomed", error.Code);
            Assert.Contains("rollback", fixture.Storage.Events);
            Assert.False(File.Exists(fixture.PathName));
            fixture.Schemas.DuringValidate = null;
            var accepted = Committed(await fixture.CreateEvent());
            var reopened = new FileJournalRecordWriteStore(fixture.PathName);
            Assert.Single((await reopened.HistoryAsync(Tenant, accepted.Receipt.RecordId)).Versions);
        }
        using var path = new JournalPath();
        var parent = Path.Combine(path.DirectoryName, "blocked-parent");
        Directory.CreateDirectory(parent);
        var journal = Path.Combine(parent, "records.json");
        var ioStore = new FileJournalRecordWriteStore(journal, new Clock(
            Evidence(Event("r1").GetProperty("entry").GetProperty("Temporal")).AuthorityRecordedAt));
        Directory.Delete(parent);
        File.WriteAllText(parent, "foreign scratch evidence");
        await Assert.ThrowsAsync<IOException>(() => AppendTemporal(ioStore, Event("r1")));
        Assert.Equal("foreign scratch evidence", File.ReadAllText(parent));
        Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp", SearchOption.AllDirectories));
        File.Delete(parent);
    }

