    [Theory]
    [InlineData("\"Ignored\":\"\\ud800\",")]
    [InlineData("\"Ignored\\ud800\":0,")]
    [InlineData("\"Ignored\":{\"nested\":[\"\\udc00\"]},")]
    [InlineData("\"Ignored\":{\"nested\\ud800\":[0]},")]
    public async Task Temporal_conversion_scans_complete_one_and_two_sources_before_output(string inserted)
    {
        using var path = new JournalPath();
        foreach (var oldFormat in new[] { 1, 2 })
        {
            byte[] poisoned;
            if (oldFormat == 1)
            {
                var original = File.ReadAllBytes(RecordWriteJournalBindingTests.Fixture("Q31/journal/records.json"));
                poisoned = Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(original).Insert(1, inserted));
            }
            else
            {
                var original = Encoding.UTF8.GetString(Mixed("M1-ordinary-converts-to-2"));
                using var document = JsonDocument.Parse(original);
                var legacy = document.RootElement.GetProperty("Entries")[0].GetProperty("Legacy").GetRawText();
                poisoned = Encoding.UTF8.GetBytes(original.Replace(legacy, legacy.Insert(1, inserted), StringComparison.Ordinal));
                Assert.NotEqual(original, Encoding.UTF8.GetString(poisoned));
            }
            File.WriteAllBytes(path.FileName, poisoned);
            var store = new FileJournalRecordWriteStore(path.FileName, new Clock(AuthorityAt));
            await Assert.ThrowsAsync<InvalidDataException>(() => AppendTemporal(store, Event("r1")));
            Assert.Equal(poisoned, File.ReadAllBytes(path.FileName));
            Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp"));
        }
    }

    [Fact]
    public async Task Actual_pre_replace_move_failure_keeps_source_and_allows_real_retry()
    {
        using var path = new JournalPath();
        var original = Mixed("M1-ordinary-converts-to-2");
        File.WriteAllBytes(path.FileName, original);
        var reached = 0;
        var clock = new Clock(Evidence(Event("r1").GetProperty("entry").GetProperty("Temporal")).AuthorityRecordedAt);
        var failing = new FileJournalRecordWriteStore(path.FileName, clock, null, () =>
        {
            reached++;
            File.Move(path.FileName, path.DirectoryName);
        });
        var error = await Record.ExceptionAsync(() => AppendTemporal(failing, Event("r1")));
        Assert.True(error is IOException or UnauthorizedAccessException);
        Assert.Equal(1, reached);
        Assert.Equal(original, File.ReadAllBytes(path.FileName));
        Assert.Empty(Directory.GetFiles(path.DirectoryName, "*.tmp"));
        var retry = await AppendTemporal(new FileJournalRecordWriteStore(path.FileName, clock), Event("r1"));
        Assert.Equal(RecordTemporalCommitDisposition.Created, retry.Disposition);
        Assert.Equal("a1462eba94b9c7726fe9608c89485091538f5afb77961e0210191a3a0569ea5b", retry.Receipt!.BindingHash);
        Assert.Single((await new FileJournalRecordWriteStore(path.FileName).HistoryAsync("acme", "rec-001")).Versions);
    }

    // A separate SPEC-framed reference, used only to retain valid hashes while attacking association rules.
    // Its unchanged message is checked against the supplied literal r1, independent of the production encoder.
    private static string ReferenceHash(JsonObject entry, string? publicationBindingHex = null)
    {
        var pieces = new List<byte[]> { Encoding.UTF8.GetBytes("hlp.records.temporal-binding/1\0") };
        byte[] S(string value) { var bytes = new UTF8Encoding(false, true).GetBytes(value); return LP(bytes); }
        byte[] LP(byte[] bytes)
        {
            var prefix = new byte[4]; BinaryPrimitives.WriteUInt32BigEndian(prefix, checked((uint)bytes.Length));
            return prefix.Concat(bytes).ToArray();
        }
        byte[] O(JsonNode? value) => value is null ? [0] : new byte[] { 1 }.Concat(S(value.GetValue<string>())).ToArray();
        byte[] T(string text)
        {
            var time = Date(text); var bytes = new byte[10];
            BinaryPrimitives.WriteUInt64BigEndian(bytes, checked((ulong)time.UtcTicks));
            BinaryPrimitives.WriteInt16BigEndian(bytes.AsSpan(8), checked((short)time.Offset.TotalMinutes));
            return bytes;
        }
        byte[] OT(JsonNode? value) => value is null ? [0] : new byte[] { 1 }.Concat(T(value.GetValue<string>())).ToArray();
        byte[] U64(long value) { var bytes = new byte[8]; BinaryPrimitives.WriteUInt64BigEndian(bytes, checked((ulong)value)); return bytes; }
        byte[] B(JsonNode basis) => U64(basis["Revision"]!.GetValue<long>())
            .Concat(Convert.FromHexString(basis["Hash"]!.GetValue<string>())).ToArray();
        byte[] OB(JsonNode? basis) => basis is null ? [0] : new byte[] { 1 }.Concat(B(basis)).ToArray();
        string Text(JsonNode node, string key) => node[key]!.GetValue<string>();
        var row = entry["Row"]!; var operation = entry["Operation"]!; var audit = entry["Audit"]!; var temporal = entry["Temporal"]!;
        pieces.Add(LP(Convert.FromHexString(publicationBindingHex ?? Event("r1").GetProperty("publication_binding_hex").GetString()!)));
        pieces.Add(S(Text(entry, "Key"))); pieces.Add(S(Text(operation, "CommandId")));
        pieces.Add(S(Text(operation, "IdempotencyKey"))); pieces.Add(Convert.FromHexString(Text(operation, "Fingerprint")));
        foreach (var name in new[] { "RecordId", "ActorId", "OperationId" }) pieces.Add(S(Text(row, name)));
        pieces.Add(O(row["RequestedVersion"])); pieces.Add(S(Text(row, "IntentEncodingVersion")));
        pieces.Add(Convert.FromHexString(Text(row, "IntentDigest")));
        pieces.Add(SHA256.HashData(Convert.FromBase64String(Text(row, "Body")))); pieces.Add(T(Text(row, "RecordedAt")));
        foreach (var name in new[] { "OriginatorId", "AcceptedCommandId", "AcceptanceAuditId" }) pieces.Add(O(row[name]));
        pieces.Add(S(Text(audit, "AuditId"))); pieces.Add(S(Text(audit, "ActorId"))); pieces.Add(T(Text(audit, "RecordedAt")));
        pieces.Add(SHA256.HashData(Convert.FromBase64String(Text(audit, "Payload"))));
        pieces.Add(SHA256.HashData(Convert.FromBase64String(Text(audit, "AuthoritySnapshot")))); pieces.Add(O(audit["OriginatorId"]));
        pieces.Add(U64(temporal["Revision"]!.GetValue<long>())); pieces.Add(OB(temporal["Predecessor"]));
        var segments = temporal["Supersedes"]!.AsArray(); var count = new byte[4];
        BinaryPrimitives.WriteUInt32BigEndian(count, checked((uint)segments.Count)); pieces.Add(count);
        foreach (var segment in segments)
        { pieces.Add(B(segment!["Revision"]!)); pieces.Add(T(Text(segment!, "EffectiveFrom"))); pieces.Add(OT(segment!["EffectiveTo"])); }
        pieces.Add(T(Text(temporal, "EffectiveFrom"))); pieces.Add(OT(temporal["EffectiveTo"]));
        pieces.Add(O(temporal["Reason"])); pieces.Add(T(Text(temporal, "AuthorityRecordedAt")));
        return Convert.ToHexStringLower(SHA256.HashData(pieces.SelectMany(value => value).ToArray()));
    }

